<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api,requestTypeLabel,type Order,type FulfillmentForm} from '../api'
const props=defineProps<{order:Order;returning?:boolean;readonly?:boolean}>()
const form=defineModel<FulfillmentForm>({required:true})
const events=ref<{id:string;kind:string;reason:string;actor_name:string;created_at:string;lines:{product_name:string;quantity:number;unit:string}[]}[]>([])
const error=ref('')
onMounted(async()=>{try{events.value=await api(`/orders/${props.order.id}/events`)}catch(e){error.value=(e as Error).message}})
</script>
<template><div class="fulfillment-editor"><div class="review-summary"><strong>{{order.supplier_name}}</strong><small class="document-number">{{order.number}} · {{requestTypeLabel(order.request_type)}}</small><p v-if="order.request_number">来源申请 {{order.request_number}}</p><p>{{readonly?'以下为各商品累计收货、退货与待收数量。':returning?'退货会扣减现有库存，并重新形成待补货数量。':'按本次实际验收数量填写，可分多次收货。'}}</p></div><div class="table-scroll"><table><thead><tr><th>商品</th><th>采购数</th><th>累计收货</th><th>累计退货</th><th>{{order.lifecycle_state==='ACTIVE'?'待收/补货':'未交付（已结束）'}}</th><th v-if="!readonly">{{returning?'本次退货':'本次收货'}}</th></tr></thead><tbody><tr v-for="(line,index) in order.lines" :key="line.id"><td><strong>{{line.product_name}}</strong><small>{{line.unit}}</small></td><td>{{line.quantity}}</td><td>{{line.received_quantity}}</td><td>{{line.returned_quantity}}</td><td>{{line.remaining}}</td><td v-if="!readonly"><input v-model.number="form.lines[index].quantity" :aria-label="line.product_name+(returning?'退货数量':'收货数量')" class="quantity-input" type="number" min="0" :max="returning?line.net_received:line.remaining" required/></td></tr></tbody></table></div><label v-if="!readonly" class="field-block">{{returning?'退货原因（必填）':'收货说明（选填）'}}<textarea v-model="form.reason" :required="returning" maxlength="300" rows="2" :placeholder="returning?'例如：验收发现损坏，退回供应商补货':'例如：首批到货，已验收'"></textarea></label><p v-if="!readonly" class="small-copy muted">不处理的商品请填 0。超量操作或旧页面提交会被拒绝。</p><p v-if="order.closure_reason" class="form-hint">结束原因：{{order.closure_reason}}</p><div class="operation-history"><h3>收货与退货记录</h3><p v-if="error" class="form-error">{{error}}</p><div v-for="event in events" :key="event.id" class="history-entry"><strong>{{event.kind==='RECEIPT'?'采购收货':'采购退货'}} · {{event.actor_name}}</strong><small>{{event.created_at.replace('T',' ').slice(0,16)}}</small><p v-for="(line,index) in event.lines" :key="index">{{line.product_name}} · {{Math.abs(line.quantity)}} {{line.unit}}</p><p class="muted">{{event.reason||'未填写说明'}}</p></div><p v-if="!events.length&&!error" class="small-copy muted">暂无收货或退货记录。</p></div></div></template>
